@namespace sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step-item @stepClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Count - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

@namespace sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Company Name *</label>
        <input type="text" class="form-control" value="@Company" @onchange="e => UpdateField(nameof(Company), e.Value?.ToString())" />
    </div>

    <div class="mb-3">
        <label class="form-label">Job Title *</label>
        <input type="text" class="form-control" value="@Title" @onchange="e => UpdateField(nameof(Title), e.Value?.ToString())" />
    </div>

    <div class="row mb-3">
        <div class="col-md-5">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateStartDate(e.Value?.ToString())" />
        </div>
        <div class="col-md-5">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateEndDate(e.Value?.ToString())" disabled="@IsCurrent" />
        </div>
        <div class="col-md-2 d-flex align-items-end">
            <div class="form-check">
                <input type="checkbox" class="form-check-input" id="current-@Index" checked="@IsCurrent" @onchange="e => UpdateIsCurrent((bool)(e.Value ?? false))" />
                <label class="form-check-label" for="current-@Index">Current</label>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" rows="3" value="@Description" @onchange="e => UpdateField(nameof(Description), e.Value?.ToString())"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryUpdate> OnEntryChanged { get; set; }

    private async Task UpdateField(string field, string? value)
    {
        await OnEntryChanged.InvokeAsync(new WorkEntryUpdate(Index, field, value));
    }

    private async Task UpdateStartDate(string? value)
    {
        await OnEntryChanged.InvokeAsync(new WorkEntryUpdate(Index, "StartDate", value));
    }

    private async Task UpdateEndDate(string? value)
    {
        await OnEntryChanged.InvokeAsync(new WorkEntryUpdate(Index, "EndDate", value));
    }

    private async Task UpdateIsCurrent(bool value)
    {
        await OnEntryChanged.InvokeAsync(new WorkEntryUpdate(Index, "IsCurrent", value.ToString()));
    }

    public record WorkEntryUpdate(int Index, string Field, string? Value);
}

@namespace sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply

<div class="reference-form">
    <h5>Reference @(Index + 1)</h5>

    <div class="mb-3">
        <label class="form-label">Name *</label>
        <input type="text" class="form-control" value="@Name" @onchange="e => UpdateField(nameof(Name), e.Value?.ToString())" />
    </div>

    <div class="mb-3">
        <label class="form-label">Relationship *</label>
        <input type="text" class="form-control" value="@Relationship" @onchange="e => UpdateField(nameof(Relationship), e.Value?.ToString())" />
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" value="@Email" @onchange="e => UpdateField(nameof(Email), e.Value?.ToString())" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" value="@Phone" @onchange="e => UpdateField(nameof(Phone), e.Value?.ToString())" />
        </div>
    </div>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
    }
    <hr />
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceUpdate> OnReferenceChanged { get; set; }

    private async Task UpdateField(string field, string? value)
    {
        await OnReferenceChanged.InvokeAsync(new ReferenceUpdate(Index, field, value ?? ""));
    }

    public record ReferenceUpdate(int Index, string Field, string Value);
}

