@namespace sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply
@using sv_db012b28ff124ef99fef861432420d86.Models

<div class="step-content">
    @if (IsSubmitted)
    {
        <div class="text-center py-5">
            <div class="mb-3">
                <span class="display-1 text-success">&#10003;</span>
            </div>
            <h3 class="text-success">Application Submitted!</h3>
            <p class="lead">Your application ID is: <strong>@ApplicationId</strong></p>
            <p>We'll be in touch soon. Thank you for applying!</p>
        </div>
    }
    else
    {
        <h3>Review & Submit</h3>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <a href="#" @onclick="() => OnEditSection.InvokeAsync(0)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@Personal.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@Personal.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@Personal.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@Personal.Address</dd>
                </dl>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <a href="#" @onclick="() => OnEditSection.InvokeAsync(1)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-3">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &ndash;
                            @(entry.EndDate.HasValue ? entry.EndDate.Value.ToString("MMM yyyy") : "Present")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <a href="#" @onclick="() => OnEditSection.InvokeAsync(2)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @foreach (var reference in References)
                {
                    <div class="mb-2">
                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
                        <small>@reference.Email &bull; @reference.Phone</small>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <a href="#" @onclick="() => OnEditSection.InvokeAsync(3)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>
        </div>

        @if (ErrorMessage != null)
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="d-flex justify-content-between mt-4">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = null!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
}

