@page "/apply"
@namespace sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply
@using sv_db012b28ff124ef99fef861432420d86.Models
@using sv_db012b28ff124ef99fef861432420d86.Services
@using static sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply.WorkEntryForm
@using static sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply.WorkHistoryStep
@using static sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply.ReferenceForm
@using static sv_db012b28ff124ef99fef861432420d86.Components.Pages.Apply.ReferencesStep
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep"
                   StepNames="@_stepNames"
                   OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName"
                                  Email="@_email"
                                  Phone="@_phone"
                                  Address="@_address"
                                  EmailError="@_emailError"
                                  ValidationMessage="@_validationMessage"
                                  IsValidating="@_isValidating"
                                  FullNameChanged="v => { _fullName = v; StateHasChanged(); }"
                                  EmailChanged="v => { _email = v; _emailError = null; StateHasChanged(); }"
                                  PhoneChanged="v => { _phone = v; StateHasChanged(); }"
                                  AddressChanged="v => { _address = v; StateHasChanged(); }"
                                  OnNext="ValidateAndAdvancePersonalInfo" />
                break;

            case 1:
                <WorkHistoryStep Entries="@_workEntries"
                                 ValidationMessage="@_validationMessage"
                                 OnAddEntry="AddWorkEntry"
                                 OnRemoveEntry="RemoveWorkEntry"
                                 OnEntryChanged="UpdateWorkEntry"
                                 OnBack="GoBack"
                                 OnNext="ValidateAndAdvanceWorkHistory" />
                break;

            case 2:
                <ReferencesStep References="@_references"
                                ValidationMessage="@_validationMessage"
                                OnAddReference="AddReference"
                                OnRemoveReference="RemoveReference"
                                OnReferenceChanged="UpdateReference"
                                OnBack="GoBack"
                                OnNext="ValidateAndAdvanceReferences" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 ValidationMessage="@_validationMessage"
                                 CoverLetterChanged="v => { _coverLetter = v; StateHasChanged(); }"
                                 OnBack="GoBack"
                                 OnNext="ValidateAndAdvanceCoverLetter" />
                break;

            case 4:
                <ReviewStep Personal="@BuildPersonalInfo()"
                            WorkEntries="@BuildWorkEntries()"
                            References="@BuildReferences()"
                            CoverLetter="@_coverLetter"
                            IsSubmitting="@_isSubmitting"
                            IsSubmitted="@_isSubmitted"
                            ApplicationId="@_applicationId"
                            ErrorMessage="@_submitError"
