+        {
+            case "Name": refEntry.Name = update.Value; break;
+            case "Relationship": refEntry.Relationship = update.Value; break;
+            case "Email": refEntry.Email = update.Value; break;
+            case "Phone": refEntry.Phone = update.Value; break;
+        }
+    }
+
+    private void ValidateAndAdvanceReferences()
+    {
+        _validationMessage = null;
+
+        foreach (var r in _references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                _validationMessage = "Please fill in all fields for each reference.";
+                return;
+            }
+        }
+
+        _currentStep = 3;
+    }
+
+    // --- Step 4: Cover Letter ---
+    private void ValidateAndAdvanceCoverLetter()
+    {
+        _validationMessage = null;
+
+        if (string.IsNullOrWhiteSpace(_coverLetter))
+        {
+            _validationMessage = "Please write a cover letter before continuing.";
+            return;
+        }
+
+        _currentStep = 4;
+    }
+
+    // --- Step 5: Submit ---
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+        _submitError = null;
+        StateHasChanged();
+
+        try
+        {
+            var application = new JobApplication(
+                BuildPersonalInfo(),
+                new WorkHistory(BuildWorkEntries()),
+                BuildReferences(),
+                _coverLetter
+            );
+
+            var id = await ApplicationService.SubmitApplicationAsync(application);
+            _applicationId = id;
+            _isSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            _submitError = $"Submission failed: {ex.Message}. Please try again.";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    // --- Builders ---
+    private PersonalInfo BuildPersonalInfo() =>
+        new(_fullName, _email, _phone, _address);
+
+    private List<WorkEntry> BuildWorkEntries() =>
+        _workEntries.Select(e => new WorkEntry(
+            e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description
+        )).ToList();
+
+    private List<Reference> BuildReferences() =>
+        _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+}
